/* RAWCRAFT SSH: byte streaming, bounded rendering and isolated session generations. */
window.RawTerminal=function(host,request,status){
 let term,fit,id='',offset=0,polling=false,opening=null,queued='',sending=false,timer,sendTimer,resizeTimer,generation=0;
 const note=s=>status?.(s);
 function resize(){clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{let session=id,epoch=generation;if(session)request('resize',{id:session,cols:term.cols,rows:term.rows}).catch(e=>{if(epoch===generation)note(e.message)})},40)}
 function ensure(){if(term)return;if(!window.Terminal||!window.FitAddon)throw Error('Brak modułu terminala. Pobierz pełną aktualizację.');term=new Terminal({fontFamily:'Consolas,Menlo,monospace',fontSize:14,scrollback:3000,cursorBlink:true,allowProposedApi:false,theme:{background:'#080b11',foreground:'#dde6f2'}});fit=new FitAddon.FitAddon();term.loadAddon(fit);term.open(host);term.onData(input);term.onResize(resize);new ResizeObserver(()=>{if(host.clientWidth&&host.clientHeight)try{fit.fit()}catch(e){}}).observe(host);document.addEventListener('visibilitychange',()=>{if(!document.hidden)schedule(0)})}
 function input(data){if(!id){note('Otwórz terminal.');return}if(queued.length+data.length>1048576){note('Poczekaj na wysłanie poprzedniego tekstu.');return}queued+=data;if(!sending&&!sendTimer)sendTimer=setTimeout(send,3)}
 async function send(){sendTimer=null;if(sending||!id)return;sending=true;let epoch=generation,session=id;try{while(queued&&session===id&&epoch===generation){let size=Math.min(8192,queued.length);let last=queued.charCodeAt(size-1);if(last>=0xD800&&last<=0xDBFF&&size<queued.length)size--;let part=queued.slice(0,size);queued=queued.slice(size);await request('write',{id:session,data:part})}}catch(e){if(epoch===generation){id='';queued='';note(e.message)}}finally{sending=false;if(queued&&id&&!sendTimer)sendTimer=setTimeout(send,0)}}
 function schedule(ms){clearTimeout(timer);if(id)timer=setTimeout(poll,ms)}
 async function poll(){if(!id||polling)return;if(document.hidden||!host.offsetParent){schedule(150);return}polling=true;let epoch=generation,session=id,delay=0;try{let d=await request('poll',{id:session,offset,waitMs:1000});if(epoch!==generation||session!==id)return;if(d.lost){term.reset();term.writeln('[Starsze dane usunięto z bufora]')}if(d.data){let bytes=Uint8Array.from(atob(d.data),c=>c.charCodeAt(0));await new Promise(resolve=>term.write(bytes,resolve));if(epoch!==generation||session!==id)return}else delay=30;offset=d.next;if(d.closed){id='';note('Sesja zakończona. Otwórz nowy terminal.')}}catch(e){if(epoch===generation&&session===id){id='';note(e.message)}}finally{polling=false;schedule(delay)}}
 async function open(){if(opening)return opening;let epoch=generation;opening=(async()=>{try{ensure();if(id){fit.fit();term.focus();schedule(0);return}note('Łączenie z terminalem…');let d=await request('open',{});if(epoch!==generation){request('close',{id:d.id}).catch(()=>{});return}id=d.id;offset=0;queued='';term.reset();fit.fit();await request('resize',{id,cols:term.cols,rows:term.rows});if(epoch!==generation)return;term.focus();note('Połączono · pełna sesja SSH');schedule(0)}catch(e){if(epoch===generation)note(e.message)}})();try{return await opening}finally{opening=null}}
 async function batch(script){await open();if(!id)throw Error('Terminal SSH nie jest połączony.');let session=id,epoch=generation;let result=await request('batch',{id:session,script});if(session!==id||epoch!==generation)throw Error('Sesja SSH zmieniła się podczas wykonywania skryptu.');return result}
 async function close(){let old=id;generation++;id='';queued='';clearTimeout(timer);clearTimeout(sendTimer);sendTimer=null;clearTimeout(resizeTimer);if(old)try{await request('close',{id:old})}catch(e){}note('Terminal zamknięty')}
 return {open,close,input,batch,fit:()=>{if(fit&&host.clientWidth)fit.fit()},focus:()=>term?.focus()};
};
